/**
 * PSE Market Cap Provider
 *
 * Reads data/pse-market-cap.json (generated by scripts/scrape-market-cap.ts,
 * which scrapes stockanalysis.com's PSE quote pages — the only free source
 * carrying a real market cap for the PSE universe; PSE Edge's disclosures
 * omit shares outstanding, and the configured EODHD / Twelve Data plans do
 * not cover PSE fundamentals).
 *
 * Values are in MILLIONS of PHP, matching inferMcapCategory() in
 * StockUniverseAdapter.ts.
 *
 * Follows the same honesty rule as PSESectorsData.ts: a missing market cap is
 * null, never a guess and never 0 — 0 would read as a real, tiny company and
 * would bucket it as "Micro Cap".
 */
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';

export interface RealPseMarketCapRecord {
  marketCap: number;
  raw: string;
  scrapedAt: string;
}

type RealMarketCapMap = Record<string, RealPseMarketCapRecord>;

let realMarketCapCache: RealMarketCapMap | null = null;

function loadRealMarketCapMap(): RealMarketCapMap {
  if (realMarketCapCache !== null) return realMarketCapCache;
  let loaded: RealMarketCapMap = {};
  try {
    const raw = readFileSync(resolve(process.cwd(), 'data/pse-market-cap.json'), 'utf-8');
    loaded = JSON.parse(raw).results ?? {};
  } catch {
    // File not generated yet (scripts/scrape-market-cap.ts hasn't been run) —
    // treat as "no real data available", not an error.
  }
  realMarketCapCache = loaded;
  return loaded;
}

/** Market cap in millions of PHP for a symbol, or null if none is available. */
export function getMarketCapBySymbol(symbol: string): number | null {
  const record = loadRealMarketCapMap()[symbol.toUpperCase()];
  return record?.marketCap ?? null;
}

/** Full scraped record (value, source string, timestamp), or null. */
export function getMarketCapRecord(symbol: string): RealPseMarketCapRecord | null {
  return loadRealMarketCapMap()[symbol.toUpperCase()] ?? null;
}

/** Clears the module cache so the next read picks up a regenerated file. */
export function reloadMarketCaps(): void {
  realMarketCapCache = null;
}
